P = [
 dict(pmid='43048582', doi='10.1021/acsestair.6c00166', journal='ACS EST Air', title='What Does Sensor Performance Really Mean? A Four-Layer Framework for Interpreting Air Quality Sensor Performance Evaluations.', tier='A', basis='Low-cost sensor / network', short='Malings group four-layer framework for reading air-quality sensor performance evaluations (who, what product, what context, what metrics)', design='Method / algorithm', pm='Fixed outdoor air-quality sensors (PM and gases); evaluation metrics as reported in sensor performance evaluations', geo='Global / multi-region', endpoint='Interpretability of sensor performance claims (no measured endpoint)', affil='Universidad del Desarrollo, Chile; TD Environmental Services, USA', n="Conceptual framework for interpreting sensor performance evaluations (SPEs) of fixed outdoor air-quality sensors, built on four questions: who led the evaluation, which data product was evaluated (raw, manufacturer-corrected, user-calibrated, cloud-processed), in what context (site, season, concentration range, co-location length), and what the metrics do and do not convey. It yields guiding questions that separate missing from uncertain information instead of ranking devices on headline R2 or RMSE. It does not set fitness-for-purpose thresholds and adds no co-location data, so its value depends on uptake by evaluators. Relevance: direct - this is the reporting layer every low-cost PM calibration paper needs; 'which data product' is the question most often left implicit behind published R2 values.", sub=corpus.SENS),
 dict(pmid='', doi='10.1021/acs.est.6c10664', journal='Environmental Science & Technology', title='Toxicity-Weighted Assessment Reveals the Rising Dominance of Non-Exhaust PM2.5 from On-Road Transportation in China', tier='A', basis='Model (CTM / LUR / ML)', short='Fudan non-exhaust (brake + tire) PM2.5 5-11x more toxic per mass than exhaust; toxicity-adjusted share 54% (2014) to 96% (2050) in China', design='Modelling / inventory', pm='Dynamometer-generated brake/tyre-wear and exhaust PM2.5; oxidative stress and cytotoxicity potencies combined with emission inventories', geo='China', endpoint='Toxicity-adjusted on-road PM2.5 emissions and exposure hotspots', affil='Fudan University, China; Fudan University, China', n='Dynamometer tests, chemical analysis and in vitro assays gave non-exhaust (brake and tyre wear) PM2.5 oxidative-stress and cytotoxicity potencies 5- to 11-fold higher per unit mass than exhaust PM2.5. Weighting Chinese on-road inventories by these potencies, toxicity-adjusted non-exhaust emissions in 2023 were about eight times exhaust; the non-exhaust share is projected to rise from 54% (2014) to 96% (2050) under electrification without dedicated controls. Weakness: the potency ratio comes from a small set of pads, tyres and engines under dynamometer conditions and in vitro endpoints, then is applied nationally with no reported uncertainty. Relevance: mass-based optical sensors cannot see this shift; a toxicity-weighted burden argues for composition or oxidative-potential proxies near roads.', sub=corpus.BURD),
 dict(pmid='43051402', doi='10.1016/j.envres.2026.126221', journal='Environ Res', title='Exposure to specific particulate matter (PM) sources and constituents are differentially associated with circulating immune biomarkers in women.', tier='B', basis='Model (CTM / LUR / ML)', short='California Teachers Study 1898 women: source/component PM0.1-PM10 and 15 immune markers; 12-mo PM2.5 EC with IL-1b, sCD27, sTNFR2', design='Cross-sectional (cohort baseline)', pm='Source- and component-resolved PM0.1, PM2.5 and PM10 at residence (modelling method not stated in abstract); 1-, 3- and 12-month means per IQR', geo='USA (California)', endpoint='Quartiles of 15 circulating immune markers (IL-1b, sCD27, sTNFR2, IL-8, CCL2, sgp130 and others)', affil='Beckman Research Institute, City of Hope, USA; University of California, Davis, USA', n='1,898 California Teachers Study women, blood drawn 2015; residential source- and component-resolved PM0.1, PM2.5 and PM10 at 1-, 3- and 12-month lags, multinomial models per IQR, Bonferroni-corrected. PM2.5 elemental carbon was associated with top-quartile IL-1b (12-month OR 2.95, 95% CI 1.94-4.48), sCD27 (2.05, 1.34-3.13) and sTNFR2 (2.70, 1.73-4.21) at every lag; PM10 off-road diesel with IL-8 (OR 1.68, 1.23-2.30) and CCL2. PM2.5 copper and PM0.1 biomass were inversely associated with sgp130, sTNFR2 and sCD27. Weakness: one blood draw, so cross-sectional; many source x marker x lag tests; modelled component surfaces with correlated errors. Relevance: EC, the component most tractable for low-cost absorption measurement, carries the strongest immune signal.', sub=corpus.MECH),
 dict(pmid='43051397', doi='10.1016/j.envres.2026.126244', journal='Environ Res', title='Size-Divergent Contributors and Interactions to PM Oxidative Potential: EC-Organics Additivity and Ion-Metal Synergy.', tier='B', basis='Lab / research instrument', short='Nankai nine-stage size-resolved PM oxidative potential: fine OP from EC + 9,10-PQ (additive), coarse OP from bioaccessible metals, ion-metal synergy', design='Laboratory measurement', pm='Size-resolved PM in nine cascade-impactor stages; ~100 components incl. bioaccessible fractions in simulated epithelial lung fluid; DTT oxidative potential', geo='China', endpoint='DTT oxidative potential (OPv) by size fraction and source (PMF + XGBoost-SHAP)', affil='Nankai University, China; Nankai University, China', n='Cascade-impactor PM in nine size fractions; ~100 components measured as ambient and lung-fluid bioaccessible concentrations, with DTT oxidative potential. Fine-particle OP was driven by elemental carbon, 9,10-phenanthrenequinone and ions, with laboratory confirmation that EC and 9,10-PQ act additively; coarse OP was dominated by bioaccessible Ni, Cu, As and Mn, ions raising OP by increasing metal bioaccessibility. PMF plus XGBoost-SHAP ranked traffic, secondary aerosol and combustion below 2.1 um, traffic and dust at 3.3-10 um. The abstract gives no sampling period, site count or effect sizes. Weakness: DTT is one acellular assay with metal-organic interferences, and SHAP importance is not source causality. Relevance: mass-only sensing misranks coarse-mode hazard; size matters beyond PM2.5.', sub=corpus.MECH),
]
